export function getImage(photo: PhotoId, crop: CropName): CropImage {
  const image = images[`${photo}:${crop}`];
  if (!image) throw new Error(`No image ${photo}:${crop}. Add the crop to assets-src/crops.json and run npm run assets.`);
  return image;
}
